/// <summary>
/// TradeDocumentReport ccontroller extension to swtich report design
/// </summary>
[ExtensionOf(classStr(TradeDocumentReportController))]
final class METTradeDocumentReportController_Extension
{
    private VendPurchOrderJour vendPurchOrderJour;
    private METLegalEntityType legaEntitytype;


}

Method.Source:
    /// <summary>
    /// Initializes the arguments and sets the report name.
    /// </summary>
    /// <param name="_args">
    /// The arguments from the caller.
    /// </param>
    /// <param name="_reportName">
    /// The name of the report to generate.
    /// </param>
    protected void initArgs(Args _args, SRSCatalogItemName _reportName)
    {
        legaEntitytype = CompanyInfo::find().METLegalEntityType;
        
        if (legaEntitytype != METLegalEntityType::None)
        {
            if (_args.record() as VendPurchOrderJour)
            {
                vendPurchOrderJour = _args.record() as VendPurchOrderJour;
            }
        }

        next initArgs(_args, _reportName);
    }

    /// <summary>
    /// Read the printmgmt settings and modify the report design
    /// </summary>
    protected void outputReport()
    {
        if (legaEntitytype != METLegalEntityType::None)
        {
            PrintMgmtPrintSettingDetail printMgmtPrintSettingDetail = formLetterReport.getCurrentPrintSetting();

            RefRecId recid = contract.parmRecordId();

            PurchTable purchTable;
            VendTable   vendTable;

            if (!vendPurchOrderJour)
            {
                vendPurchOrderJour = vendPurchOrderJour::findRecId(recid);
            }

            select firstonly PurchPoolId, OrderAccount from purchTable
                where purchTable.PurchId == VendPurchOrderJour.PurchId
            join VendGroup from vendTable
                where vendTable.AccountNum == purchTable.OrderAccount;

            if (VendTable.VendGroup == METConstants::ImportPOVendorGroup && purchTable.PurchPoolId == METConstants::ImportPOPoolId)
            {
                printMgmtPrintSettingDetail.parmReportFormatName(ssrsReportStr(METPurchPurchaseOrder, ReportImport));
            }
            else
            {
                printMgmtPrintSettingDetail.parmReportFormatName(ssrsReportStr(METPurchPurchaseOrder, ReportTrade));
            }
        }
        
        next outputReport();
    }
